/* ============================================================
   LPR image data registry — base64 data URIs for sheet-critical images.
   WHY THIS EXISTS: the site runs from file://, where drawing a file:// 
   image onto a canvas taints it, so html2canvas-based PNG/PDF exports
   silently drop every <img> and CSS background (exports shipped without
   the logo). Scripts are NOT subject to that restriction, so this file
   carries the images as data URIs; template-tools.js's inlineImgSrcs()
   and Yard Sign's hi-res exporter consult window.LPR_IMG_DATA before
   falling back to the on-disk path. Regenerate any entry by re-running:
   python -c "import base64;print(base64.b64encode(open('assets/<f>','rb').read()).decode())"
   ============================================================ */
window.LPR_IMG_DATA = {
  "logo-cropped.png": "data:image/png;base64,",
  "logo-white.png": "data:image/png;base64,",
  "eho-white.png": "data:image/png;base64,",
  "ps3817-form.png": "data:image/png;base64,",
  "logo-current.png": "data:image/png;base64,",
};